# PHOENIX SCALPER - Trading Filters
"""Session, spread, volatility, and news filters."""

from datetime import datetime, timezone
from typing import List, Tuple, Optional

from core.constants import (
    SESSION_LONDON_START, SESSION_LONDON_END,
    SESSION_NY_START, SESSION_NY_END,
    SESSION_OVERLAP_START, SESSION_OVERLAP_END,
    SESSION_ASIA_START, SESSION_ASIA_END,
    MAX_SPREAD_POINTS, GOOD_SPREAD, IDEAL_SPREAD,
)


def get_current_session(utc_hour: Optional[int] = None) -> str:
    """Determine current trading session."""
    if utc_hour is None:
        utc_hour = datetime.now(timezone.utc).hour

    if SESSION_OVERLAP_START <= utc_hour < SESSION_OVERLAP_END:
        return "London/NY Overlap"
    elif SESSION_LONDON_START <= utc_hour < SESSION_LONDON_END:
        return "London"
    elif SESSION_NY_START <= utc_hour < SESSION_NY_END:
        return "New York"
    elif SESSION_ASIA_START <= utc_hour < SESSION_ASIA_END:
        return "Asia"
    else:
        return "Off-hours"


def is_trading_session(utc_hour: Optional[int] = None) -> bool:
    """Check if we are in an active trading session for XAUUSD."""
    if utc_hour is None:
        utc_hour = datetime.now(timezone.utc).hour
    # Trade during London and NY sessions (7:00 - 21:00 UTC)
    return SESSION_LONDON_START <= utc_hour < SESSION_NY_END


def is_prime_time(utc_hour: Optional[int] = None) -> bool:
    """Check if we are in prime scalping time (overlap)."""
    if utc_hour is None:
        utc_hour = datetime.now(timezone.utc).hour
    return SESSION_OVERLAP_START <= utc_hour < SESSION_OVERLAP_END


def get_session_quality(utc_hour: Optional[int] = None) -> float:
    """Get session quality score 0-1 (higher = better for scalping)."""
    if utc_hour is None:
        utc_hour = datetime.now(timezone.utc).hour

    if SESSION_OVERLAP_START <= utc_hour < SESSION_OVERLAP_END:
        return 1.0  # Best time
    elif SESSION_LONDON_START <= utc_hour < SESSION_LONDON_END:
        return 0.8
    elif SESSION_NY_START <= utc_hour < SESSION_NY_END:
        return 0.7
    elif SESSION_ASIA_START <= utc_hour < SESSION_ASIA_END:
        return 0.3  # Low volatility for gold
    else:
        return 0.0


def check_spread(spread_points: int,
                 max_spread: int = MAX_SPREAD_POINTS) -> Tuple[bool, str, float]:
    """Check spread quality. Returns (ok, message, quality_score)."""
    if spread_points > max_spread:
        return False, f"Spread too high: {spread_points} > {max_spread}", 0.0
    if spread_points <= IDEAL_SPREAD:
        return True, f"Ideal spread: {spread_points}", 1.0
    if spread_points <= GOOD_SPREAD:
        return True, f"Good spread: {spread_points}", 0.8
    return True, f"Acceptable spread: {spread_points}", 0.5


def check_news_block(news_times: List[str],
                     block_minutes: int = 30) -> Tuple[bool, str]:
    """Check if trading is blocked by scheduled news events."""
    if not news_times:
        return False, "No news events"

    now = datetime.now(timezone.utc)
    current_mins = now.hour * 60 + now.minute

    for t_str in news_times:
        try:
            parts = t_str.split(":")
            news_mins = int(parts[0]) * 60 + int(parts[1])
            diff = abs(current_mins - news_mins)
            if diff <= block_minutes:
                remaining = block_minutes - diff
                return True, f"News block: {t_str} UTC ({remaining}min left)"
        except (ValueError, IndexError):
            continue
    return False, "No active news blocks"


def check_volatility(atr: float, atr_avg: float) -> Tuple[str, float]:
    """Assess market volatility. Returns (condition, multiplier).

    multiplier: applied to position size (< 1.0 = reduce, > 1.0 = increase).
    """
    if atr_avg <= 0:
        return "unknown", 1.0

    ratio = atr / atr_avg
    if ratio < 0.4:
        return "very_low", 0.6       # Reduce size, moves are small
    elif ratio < 0.7:
        return "low", 0.8            # Slightly reduce
    elif ratio < 1.3:
        return "normal", 1.0         # Standard
    elif ratio < 2.0:
        return "high", 0.9           # Slightly reduce (wider moves but riskier)
    else:
        return "extreme", 0.0        # Don't trade


def get_market_condition(adx: float, bb_bandwidth: float) -> str:
    """Determine overall market condition."""
    if adx > 30 and bb_bandwidth > 0.008:
        return "strong_trend"
    elif adx > 22:
        return "trending"
    elif bb_bandwidth < 0.004:
        return "tight_range"
    elif adx < 18:
        return "ranging"
    else:
        return "mixed"


def is_weekend() -> bool:
    """Check if current day is weekend."""
    return datetime.now(timezone.utc).weekday() >= 5


def apply_all_filters(spread: int, atr: float, atr_avg: float,
                      news_times: List[str], news_block_minutes: int,
                      max_spread: int = MAX_SPREAD_POINTS) -> Tuple[bool, str, float]:
    """Apply all pre-trade filters.

    Returns (can_trade, reason_if_blocked, volatility_multiplier).
    """
    # Weekend check
    if is_weekend():
        return False, "Market closed (weekend)", 0.0

    # Session filter
    if not is_trading_session():
        session = get_current_session()
        return False, f"Outside trading hours: {session}", 0.0

    # Spread filter
    spread_ok, spread_msg, _ = check_spread(spread, max_spread)
    if not spread_ok:
        return False, spread_msg, 0.0

    # News filter
    news_blocked, news_msg = check_news_block(news_times, news_block_minutes)
    if news_blocked:
        return False, news_msg, 0.0

    # Volatility filter
    vol_cond, vol_mult = check_volatility(atr, atr_avg)
    if vol_cond == "extreme":
        return False, f"Extreme volatility (ATR ratio={atr / atr_avg:.2f})", 0.0

    return True, "All filters passed", vol_mult

