# PHOENIX SCALPER - Profit Lock System
"""Profit protection: break-even, trailing stop, partial close."""

from typing import Dict, Optional

from core.constants import (
    BUY, SELL,
    BE_TRIGGER_R, LOCK_TRIGGER_R, TRAIL_TRIGGER_R,
    PARTIAL_CLOSE_PCT, PARTIAL_TRIGGER_R, TRAIL_ATR_MULT,
)
from core.state import RobotState


class ProfitLockManager:
    """Smart profit protection optimized for scalping."""

    def __init__(self, state: RobotState):
        self.state = state

    def check(self, position: Dict, current_price: float,
              atr: float) -> Optional[Dict]:
        """Check and return profit lock action if needed.

        Returns action dict or None:
        - {"type": "modify_sl", "new_sl": float, "reason": str}
        - {"type": "partial_close", "close_pct": float, "reason": str}
        - {"type": "close", "reason": str}
        """
        if not position:
            return None

        entry = position.get("price_open", 0.0)
        current_sl = position.get("sl", 0.0)
        direction = position.get("type", BUY)
        sl_distance = position.get("sl_distance", atr)

        if sl_distance <= 0:
            sl_distance = atr
        if sl_distance <= 0:
            return None

        # Calculate R-multiple (profit in terms of initial risk)
        if direction == BUY:
            profit_distance = current_price - entry
        else:
            profit_distance = entry - current_price

        r_multiple = profit_distance / sl_distance

        # === 1. Break-even at 0.6R ===
        if r_multiple >= BE_TRIGGER_R and not self.state.be_active:
            buffer = sl_distance * 0.08  # Small buffer above entry
            if direction == BUY:
                new_sl = entry + buffer
                if new_sl > current_sl:
                    self.state.update(be_active=True)
                    return {
                        "type": "modify_sl",
                        "new_sl": round(new_sl, 2),
                        "reason": f"Break-even at {r_multiple:.1f}R",
                    }
            else:
                new_sl = entry - buffer
                if current_sl <= 0 or new_sl < current_sl:
                    self.state.update(be_active=True)
                    return {
                        "type": "modify_sl",
                        "new_sl": round(new_sl, 2),
                        "reason": f"Break-even at {r_multiple:.1f}R",
                    }

        # === 2. Lock profit at 1.0R ===
        if r_multiple >= LOCK_TRIGGER_R and not self.state.profit_locked:
            lock = sl_distance * 0.35  # Lock 35% of risk as profit
            if direction == BUY:
                new_sl = entry + lock
                if new_sl > current_sl:
                    self.state.update(profit_locked=True)
                    return {
                        "type": "modify_sl",
                        "new_sl": round(new_sl, 2),
                        "reason": f"Profit locked at {r_multiple:.1f}R",
                    }
            else:
                new_sl = entry - lock
                if current_sl <= 0 or new_sl < current_sl:
                    self.state.update(profit_locked=True)
                    return {
                        "type": "modify_sl",
                        "new_sl": round(new_sl, 2),
                        "reason": f"Profit locked at {r_multiple:.1f}R",
                    }

        # === 3. Partial close at 1.2R ===
        if r_multiple >= PARTIAL_TRIGGER_R and not self.state.partial_closed:
            self.state.update(partial_closed=True)
            return {
                "type": "partial_close",
                "close_pct": PARTIAL_CLOSE_PCT,
                "reason": f"Partial close {PARTIAL_CLOSE_PCT * 100:.0f}% at {r_multiple:.1f}R",
            }

        # === 4. Trailing stop after 1.3R ===
        if r_multiple >= TRAIL_TRIGGER_R:
            trail_dist = atr * TRAIL_ATR_MULT
            if direction == BUY:
                new_sl = current_price - trail_dist
                if new_sl > current_sl:
                    self.state.update(
                        trailing_active=True,
                        trailing_level=new_sl,
                    )
                    return {
                        "type": "modify_sl",
                        "new_sl": round(new_sl, 2),
                        "reason": f"Trailing at {r_multiple:.1f}R (dist={trail_dist:.2f})",
                    }
            else:
                new_sl = current_price + trail_dist
                if current_sl <= 0 or new_sl < current_sl:
                    self.state.update(
                        trailing_active=True,
                        trailing_level=new_sl,
                    )
                    return {
                        "type": "modify_sl",
                        "new_sl": round(new_sl, 2),
                        "reason": f"Trailing at {r_multiple:.1f}R (dist={trail_dist:.2f})",
                    }

        return None

    def check_time_exit(self, position: Dict,
                        max_hold_minutes: int = 30) -> bool:
        """Check if position exceeded max hold time."""
        import time
        open_time = position.get("time", 0)
        if open_time <= 0:
            return False
        elapsed = time.time() - open_time
        return elapsed > max_hold_minutes * 60

    def check_session_exit(self, position: Dict) -> bool:
        """Check if trading session is ending - close positions."""
        from strategy.filters import is_trading_session
        return not is_trading_session()

    def reset(self) -> None:
        """Reset profit lock state for new trade."""
        self.state.reset_profit_lock()

