# PHOENIX SCALPER - MetaTrader 5 Connector
"""Robust MT5 communication with auto-reconnect, filling detection, and retry logic."""

import time
import threading
import sys
from datetime import datetime, timezone
from typing import Optional, Dict, List, Tuple, Any

from core.constants import MAGIC_DEMO, MAGIC_LIVE, BUY, SELL

try:
    import MetaTrader5 as mt5
    MT5_AVAILABLE = True
except ImportError:
    MT5_AVAILABLE = False


def _log(msg: str, level: str = "info") -> None:
    """Print colored log message."""
    colors = {
        "ok": "\033[92m",
        "error": "\033[91m",
        "warn": "\033[93m",
        "info": "\033[96m",
    }
    prefixes = {
        "ok": "[OK]",
        "error": "[ERROR]",
        "warn": "[WARNING]",
        "info": "[INFO]",
    }
    c = colors.get(level, "\033[0m")
    p = prefixes.get(level, "[INFO]")
    print(f"  {c}{p}\033[0m {msg}")
    sys.stdout.flush()


class MT5Connector:
    """MetaTrader 5 connection and order execution layer."""

    def __init__(self, terminal_path: str = "", login: int = 0,
                 password: str = "", server: str = "",
                 magic_number: int = MAGIC_DEMO, timeout: int = 10000,
                 mode: str = "demo"):
        self.terminal_path = terminal_path
        self.login = login
        self.password = password
        self.server = server
        self.magic_number = magic_number
        self.timeout = timeout
        self.mode = mode
        self._connected = False
        self._last_heartbeat: Optional[datetime] = None
        self._heartbeat_thread: Optional[threading.Thread] = None
        self._heartbeat_running = False
        self._filling_type: Optional[int] = None

    @property
    def connected(self) -> bool:
        return self._connected

    def initialize(self, max_retries: int = 3,
                   retry_delay: int = 5) -> Tuple[bool, str]:
        """Initialize MT5 connection with retry logic."""
        if not MT5_AVAILABLE:
            _log("MetaTrader5 package not installed! Install: pip install MetaTrader5", "error")
            return False, "MetaTrader5 not installed"

        for attempt in range(1, max_retries + 1):
            _log(f"Connecting to MT5 (attempt {attempt}/{max_retries})...", "info")
            try:
                try:
                    mt5.shutdown()
                except Exception:
                    pass

                kwargs: Dict[str, Any] = {}
                if self.terminal_path:
                    kwargs["path"] = self.terminal_path
                if self.login:
                    kwargs["login"] = self.login
                if self.password:
                    kwargs["password"] = self.password
                if self.server:
                    kwargs["server"] = self.server
                if self.timeout:
                    kwargs["timeout"] = self.timeout

                safe = {k: ("***" if k == "password" else v) for k, v in kwargs.items()}
                _log(f"Params: {safe}", "info")

                if not mt5.initialize(**kwargs):
                    err = mt5.last_error()
                    _log(f"Init failed: {err}", "error")
                    if attempt < max_retries:
                        _log(f"Retrying in {retry_delay}s...", "warn")
                        time.sleep(retry_delay)
                        continue
                    return False, f"Init failed: {err}"

                self._connected = True
                self._last_heartbeat = datetime.now(timezone.utc)

                # Display account info
                account = mt5.account_info()
                terminal = mt5.terminal_info()

                if account:
                    mode_name = {0: "DEMO", 1: "CONTEST", 2: "REAL"}.get(account.trade_mode, "?")
                    _log(f"Account: {account.login} @ {account.server} ({mode_name})", "ok")
                    _log(f"Name: {account.name} | Broker: {account.company}", "ok")
                    _log(f"Balance: {account.balance} {account.currency} | Equity: {account.equity}", "ok")
                    _log(f"Leverage: 1:{account.leverage}", "ok")

                if terminal:
                    _log(f"Terminal: {terminal.name} (build {terminal.build})", "ok")
                    if terminal.trade_allowed:
                        _log("AutoTrading: ENABLED", "ok")
                    else:
                        _log("AutoTrading: DISABLED - Enable in MT5!", "warn")
                    _log(f"Server connected: {terminal.connected}", "ok")

                self._detect_filling_type()
                _log("MT5 connected successfully!", "ok")
                return True, "Connected"

            except Exception as e:
                _log(f"Init error: {e}", "error")
                if attempt < max_retries:
                    time.sleep(retry_delay)
                    continue
                return False, str(e)

        return False, "All retries failed"

    def _detect_filling_type(self, symbol: str = "") -> None:
        """Auto-detect supported order filling type."""
        if not MT5_AVAILABLE or not self._connected:
            return

        symbols_to_try = []
        if symbol:
            symbols_to_try.append(symbol)
        symbols_to_try.extend(["XAUUSD", "XAUUSD+", "GOLD", "XAUUSDm"])

        try:
            info = None
            for sym in symbols_to_try:
                info = mt5.symbol_info(sym)
                if info is None:
                    mt5.symbol_select(sym, True)
                    time.sleep(0.3)
                    info = mt5.symbol_info(sym)
                if info is not None:
                    _log(f"Symbol found: {sym}", "ok")
                    break

            if info is not None:
                fm = info.filling_mode
                if fm & 1:
                    self._filling_type = mt5.ORDER_FILLING_FOK
                    _log("Filling: FOK", "ok")
                elif fm & 2:
                    self._filling_type = mt5.ORDER_FILLING_IOC
                    _log("Filling: IOC", "ok")
                else:
                    self._filling_type = mt5.ORDER_FILLING_RETURN
                    _log("Filling: RETURN", "ok")
            else:
                self._filling_type = mt5.ORDER_FILLING_FOK
                _log("Filling: FOK (default, no symbol found)", "warn")
        except Exception as e:
            self._filling_type = mt5.ORDER_FILLING_FOK if MT5_AVAILABLE else None
            _log(f"Filling detection error: {e}", "warn")

    def _get_filling(self, symbol: str) -> int:
        """Get filling type for a symbol."""
        if self._filling_type is not None:
            return self._filling_type
        if not MT5_AVAILABLE:
            return 0
        try:
            info = mt5.symbol_info(symbol)
            if info:
                fm = info.filling_mode
                if fm & 1:
                    return mt5.ORDER_FILLING_FOK
                elif fm & 2:
                    return mt5.ORDER_FILLING_IOC
                return mt5.ORDER_FILLING_RETURN
        except Exception:
            pass
        return mt5.ORDER_FILLING_FOK

    def shutdown(self) -> None:
        """Disconnect from MT5."""
        self.stop_heartbeat()
        if MT5_AVAILABLE and self._connected:
            try:
                mt5.shutdown()
                _log("MT5 disconnected", "info")
            except Exception:
                pass
        self._connected = False

    def check_connection(self) -> Tuple[bool, str]:
        """Verify MT5 connection is alive."""
        if not MT5_AVAILABLE or not self._connected:
            return False, "Not connected"
        try:
            info = mt5.terminal_info()
            if info is None:
                self._connected = False
                return False, "Terminal not responding"
            if not info.connected:
                return False, "Not connected to broker server"
            self._last_heartbeat = datetime.now(timezone.utc)
            return True, "OK"
        except Exception as e:
            self._connected = False
            return False, str(e)

    def reconnect(self) -> Tuple[bool, str]:
        """Attempt reconnection."""
        _log("Attempting reconnection...", "warn")
        self.shutdown()
        time.sleep(2)
        return self.initialize(max_retries=2, retry_delay=3)

    def start_heartbeat(self, interval: int = 15) -> None:
        """Start background heartbeat thread."""
        self._heartbeat_running = True
        self._heartbeat_thread = threading.Thread(
            target=self._heartbeat_loop, args=(interval,), daemon=True)
        self._heartbeat_thread.start()

    def stop_heartbeat(self) -> None:
        """Stop heartbeat thread."""
        self._heartbeat_running = False
        if self._heartbeat_thread:
            self._heartbeat_thread.join(timeout=5)

    def _heartbeat_loop(self, interval: int) -> None:
        """Heartbeat with auto-reconnect."""
        fails = 0
        while self._heartbeat_running:
            ok, _ = self.check_connection()
            if ok:
                fails = 0
            else:
                fails += 1
                if fails >= 3:
                    ok, _ = self.reconnect()
                    if ok:
                        fails = 0
            time.sleep(interval)

    def get_account_info(self) -> Optional[Dict]:
        """Get current account info."""
        if not self._connected or not MT5_AVAILABLE:
            return None
        try:
            info = mt5.account_info()
            if info is None:
                return None
            return {
                "login": info.login, "server": info.server,
                "balance": info.balance, "equity": info.equity,
                "margin": info.margin, "margin_free": info.margin_free,
                "margin_level": info.margin_level if info.margin > 0 else 0,
                "profit": info.profit, "currency": info.currency,
                "leverage": info.leverage, "name": info.name,
                "company": info.company, "trade_mode": info.trade_mode,
            }
        except Exception:
            return None

    def is_autotrading_enabled(self) -> bool:
        """Check if AutoTrading is on."""
        if not self._connected or not MT5_AVAILABLE:
            return False
        try:
            info = mt5.terminal_info()
            return info.trade_allowed if info else False
        except Exception:
            return False

    def get_symbol_info(self, symbol: str) -> Optional[Dict]:
        """Get symbol details."""
        if not self._connected or not MT5_AVAILABLE:
            return None
        try:
            info = mt5.symbol_info(symbol)
            if info is None:
                mt5.symbol_select(symbol, True)
                time.sleep(0.5)
                info = mt5.symbol_info(symbol)
            if info is None:
                return None
            return {
                "name": info.name, "bid": info.bid, "ask": info.ask,
                "spread": info.spread, "point": info.point,
                "digits": info.digits,
                "trade_contract_size": info.trade_contract_size,
                "volume_min": info.volume_min, "volume_max": info.volume_max,
                "volume_step": info.volume_step,
                "trade_tick_value": info.trade_tick_value,
                "trade_tick_size": info.trade_tick_size,
                "filling_mode": info.filling_mode,
            }
        except Exception:
            return None

    def get_tick(self, symbol: str) -> Optional[Dict]:
        """Get latest tick."""
        if not self._connected or not MT5_AVAILABLE:
            return None
        try:
            tick = mt5.symbol_info_tick(symbol)
            if tick is None:
                return None
            return {
                "bid": tick.bid, "ask": tick.ask,
                "last": tick.last, "volume": tick.volume, "time": tick.time,
            }
        except Exception:
            return None

    def get_candles(self, symbol: str, timeframe_str: str,
                    count: int = 500) -> Optional[List[Dict]]:
        """Get OHLCV candle data."""
        if not self._connected or not MT5_AVAILABLE:
            return None
        try:
            tf_map = {
                "M1": mt5.TIMEFRAME_M1, "M5": mt5.TIMEFRAME_M5,
                "M15": mt5.TIMEFRAME_M15, "M30": mt5.TIMEFRAME_M30,
                "H1": mt5.TIMEFRAME_H1, "H4": mt5.TIMEFRAME_H4,
                "D1": mt5.TIMEFRAME_D1,
            }
            tf = tf_map.get(timeframe_str, mt5.TIMEFRAME_M5)
            mt5.symbol_select(symbol, True)

            rates = mt5.copy_rates_from_pos(symbol, tf, 0, count)
            if rates is None or len(rates) == 0:
                err = mt5.last_error()
                _log(f"No candles for {symbol} {timeframe_str}: {err}", "warn")
                return None

            candles = []
            for r in rates:
                candles.append({
                    "time": r[0], "open": float(r[1]), "high": float(r[2]),
                    "low": float(r[3]), "close": float(r[4]),
                    "tick_volume": int(r[5]), "spread": int(r[6]),
                    "real_volume": int(r[7]),
                })
            return candles
        except Exception as e:
            _log(f"Candle error: {e}", "error")
            return None

    def send_order(self, symbol: str, direction: str, lot: float,
                   sl: float, tp: float,
                   comment: str = "PHOENIX") -> Tuple[str, int, str]:
        """Send market order. Returns (state, ticket, message)."""
        if not self._connected or not MT5_AVAILABLE:
            return "FAILED", 0, "Not connected"

        try:
            mt5.symbol_select(symbol, True)
            time.sleep(0.1)

            sym = mt5.symbol_info(symbol)
            if sym is None:
                return "FAILED", 0, f"Symbol {symbol} not found"

            price = sym.ask if direction == BUY else sym.bid
            order_type = mt5.ORDER_TYPE_BUY if direction == BUY else mt5.ORDER_TYPE_SELL

            # Validate lot
            lot = max(sym.volume_min, lot)
            lot = min(sym.volume_max, lot)
            if sym.volume_step > 0:
                lot = round(lot / sym.volume_step) * sym.volume_step
                lot = round(lot, 2)

            # Round prices
            d = sym.digits
            sl = round(sl, d)
            tp = round(tp, d)
            price = round(price, d)

            filling = self._get_filling(symbol)

            request = {
                "action": mt5.TRADE_ACTION_DEAL,
                "symbol": symbol,
                "volume": lot,
                "type": order_type,
                "price": price,
                "sl": sl,
                "tp": tp,
                "deviation": 20,
                "magic": self.magic_number,
                "comment": comment,
                "type_time": mt5.ORDER_TIME_GTC,
                "type_filling": filling,
            }

            _log(f"Order: {direction} {lot} {symbol} @ {price} SL={sl} TP={tp}", "info")

            result = mt5.order_send(request)
            if result is None:
                err = mt5.last_error()
                return "FAILED", 0, f"Order send returned None: {err}"

            if result.retcode == mt5.TRADE_RETCODE_DONE:
                _log(f"Order executed: ticket={result.order}", "ok")
                return "EXECUTED", result.order, "Order executed"

            # Retry with different filling type if rejected
            if result.retcode in (mt5.TRADE_RETCODE_INVALID_FILL, 10030):
                for alt_fill in [mt5.ORDER_FILLING_IOC, mt5.ORDER_FILLING_RETURN, mt5.ORDER_FILLING_FOK]:
                    if alt_fill == filling:
                        continue
                    request["type_filling"] = alt_fill
                    result = mt5.order_send(request)
                    if result and result.retcode == mt5.TRADE_RETCODE_DONE:
                        self._filling_type = alt_fill
                        _log(f"Order executed (alt fill): ticket={result.order}", "ok")
                        return "EXECUTED", result.order, "Order executed"

            msg = f"Order rejected: {result.retcode} - {result.comment}"
            _log(msg, "error")
            return "FAILED", 0, msg

        except Exception as e:
            _log(f"Order exception: {e}", "error")
            return "FAILED", 0, str(e)

    def modify_position(self, ticket: int, symbol: str,
                        sl: float, tp: float) -> Tuple[bool, str]:
        """Modify position SL/TP."""
        if not self._connected or not MT5_AVAILABLE:
            return False, "Not connected"
        try:
            sym = mt5.symbol_info(symbol)
            d = sym.digits if sym else 2
            request = {
                "action": mt5.TRADE_ACTION_SLTP,
                "symbol": symbol,
                "position": ticket,
                "sl": round(sl, d),
                "tp": round(tp, d),
            }
            result = mt5.order_send(request)
            if result and result.retcode == mt5.TRADE_RETCODE_DONE:
                return True, "Modified"
            msg = f"Modify failed: {result.retcode if result else 'None'}"
            return False, msg
        except Exception as e:
            return False, str(e)

    def close_position(self, ticket: int, symbol: str,
                       lot: float, direction: str) -> Tuple[bool, str]:
        """Close a position."""
        if not self._connected or not MT5_AVAILABLE:
            return False, "Not connected"
        try:
            mt5.symbol_select(symbol, True)
            sym = mt5.symbol_info(symbol)
            if sym is None:
                return False, "Symbol not found"

            close_type = mt5.ORDER_TYPE_SELL if direction == BUY else mt5.ORDER_TYPE_BUY
            price = sym.bid if direction == BUY else sym.ask

            if sym.volume_step > 0:
                lot = round(lot / sym.volume_step) * sym.volume_step
                lot = round(lot, 2)
            lot = max(sym.volume_min, lot)

            request = {
                "action": mt5.TRADE_ACTION_DEAL,
                "symbol": symbol,
                "volume": lot,
                "type": close_type,
                "position": ticket,
                "price": round(price, sym.digits),
                "deviation": 20,
                "magic": self.magic_number,
                "comment": "PHOENIX_CLOSE",
                "type_time": mt5.ORDER_TIME_GTC,
                "type_filling": self._get_filling(symbol),
            }

            result = mt5.order_send(request)
            if result and result.retcode == mt5.TRADE_RETCODE_DONE:
                _log(f"Position closed: ticket={ticket}", "ok")
                return True, "Closed"

            msg = f"Close failed: {result.retcode if result else 'None'}"
            _log(msg, "error")
            return False, msg
        except Exception as e:
            return False, str(e)

    def get_open_positions(self, symbol: str = "") -> List[Dict]:
        """Get open positions."""
        if not self._connected or not MT5_AVAILABLE:
            return []
        try:
            if symbol:
                positions = mt5.positions_get(symbol=symbol)
            else:
                positions = mt5.positions_get()
            if positions is None:
                return []
            result = []
            for p in positions:
                result.append({
                    "ticket": p.ticket, "symbol": p.symbol,
                    "type": BUY if p.type == 0 else SELL,
                    "volume": p.volume, "price_open": p.price_open,
                    "price_current": p.price_current,
                    "sl": p.sl, "tp": p.tp,
                    "profit": p.profit, "swap": p.swap,
                    "magic": p.magic, "comment": p.comment,
                    "time": p.time,
                })
            return result
        except Exception:
            return []

    def get_point_value(self, symbol: str) -> float:
        """Get point value for lot size calculation."""
        info = self.get_symbol_info(symbol)
        if info:
            tick_value = info.get("trade_tick_value", 1.0)
            tick_size = info.get("trade_tick_size", 0.01)
            if tick_size > 0:
                return tick_value / tick_size
        return 1.0
